input.command:
cat > /app/git-deploy.conf <<'EOF'
server {
    listen 8443 ssl;
    server_name localhost;

    ssl_certificate /etc/nginx/ssl/selfsigned.crt;
    ssl_certificate_key /etc/nginx/ssl/selfsigned.key;

    location = /index.html {
        root /var/www/main;
    }

    location = / {
        root /var/www/main;
        index index.html;
    }

    location /dev/ {
        alias /var/www/dev/;
        index index.html;
    }

    location / {
        root /var/www/main;
    }
}
EOF
cp /app/git-deploy.conf /etc/nginx/sites-available/git-deploy.conf 2>/dev/null || cp /app/git-deploy.conf /etc/nginx/conf.d/git-deploy.conf
ls /etc/nginx/sites-enabled/ /etc/nginx/conf.d/ 2>/dev/null
